-- Publish the six founder essays imported from the legacy site.
-- This is an upsert because migrations run before seed.sql on a clean reset,
-- while deployed environments may already hold the original retired rows.

insert into public.categories (slug, name, description, sort_order)
values ('essays', 'Essays', 'Founder notes on layoffs, work, and why Offboard exists.', 2)
on conflict (slug) do update set
  name = excluded.name,
  description = excluded.description,
  sort_order = excluded.sort_order;

insert into public.posts (
  slug, title, category_slug, excerpt, reading_time, date, author_name,
  author_role, related, status, body, sort_order
)
values
  ('this-is-not-charity-it-is-reconstruction', 'This Is Not Charity. It Is Reconstruction.', 'essays', 'A raw, personal account of life after layoff: the rage, the despair, and the third path between torching everything and disappearing. Why Offboard exists.', '4 min read', '2026-04-16', 'Steph', 'Founder', ARRAY['we-forgot-to-reinforce-the-foundations', 'they-think-an-idea-is-bulletproof-they-are-wrong'], 'published', '[{"type":"p","runs":["I took my job seriously."]},{"type":"p","runs":["Every shift was another brick in the wall I was building for my family. I wanted them to have stability, a roof that never leaked, and the kind of life where birthdays did not come with whispered calculations about whether we could afford cake. That was my north star."]},{"type":"p","runs":["Then the layoff notice came from a manager younger than me who could not perform the simplest tasks I handled daily. She signed the paperwork that ended my paycheck and kept climbing the corporate ladder anyway. In that moment, something inside me snapped. I did not torch the Amazon warehouse. I wanted to. The rage was real and raw."]},{"type":"p","runs":["But I also wanted to end my life."]},{"type":"p","runs":["That''s not theatre or clickbait. It''s how"," ",{"b":["MOST"]}," of the people who come to me feel after a layoff. Those two impulses sit side by side like twin demons whispering the same lie: nothing will ever change."]},{"type":"p","runs":["My children became the guardrails. They are the reason I woke up instead of doing the unthinkable. They are the reason I started volunteering more, and chose to breathe instead of break. That choice is the only reason I am still here to write this."]},{"type":"p","runs":["Yet every day I see the same story repeating across the country. People arrive at Offboard carrying the same two options in their hearts: torch the employer or die trying to stay loyal. There is almost nothing in between. The sentiment in the United States right now is that a revolution is either coming or already here."]},{"type":"p","runs":["It is not the kind with pitchforks in the streets yet."]},{"type":"p","runs":["It is quieter and more dangerous."]},{"type":"p","runs":["It is a digital Trail of Tears where entire families are displaced overnight by spreadsheets and quarterly earnings calls. Loyalty has been erased. Competence has been replaced by optics. And the managers who fail upward keep failing in fields like security, where the stakes are measured in human lives."]},{"type":"divider"},{"type":"h2","text":"History Offers a Different Map"},{"type":"p","runs":["History offers a different map. The stewards of great leadership were never the distant geniuses perched on thrones. They were the ones deep in the trenches. They built loyalty through a shared vision rather than fear. They managed rival personalities without creating chaos. They adapted to the crises of their time and turned pressure into forward momentum. Horatio Nelson did not win at sea by barking orders from afar. He made every sailor feel personally invested. George VI and Clement Attlee steadied nations through war and recovery by focusing on quiet competence and real delegation. Even in the most pressured environments, such as the Manhattan Project, leaders succeeded by aligning competing tribes around a clear purpose."]},{"type":"p","runs":["These patterns repeat because they work. Bad management is not inevitable. It is a choice made by people who prioritize stock prices over human stability."]},{"type":"divider"},{"type":"h2","text":"Why We Exist"},{"type":"p","runs":["That is why ",{"a":{"text":"we exist","href":"https://app.offboard.co/auth?tab=signup"}},"."]},{"type":"p","runs":["It is not another job board. It is the processing point we are modernizing for the digital age. We take the historical playbook of trench-level leadership and turn it into practical tools anyone can use the same day they lose their income. We give away the exact stabilization steps that communities share in their darkest moments:"]},{"type":"list","ordered":false,"items":[["File for unemployment immediately,"],["Rebuild the emergency fund even if it covers only one month,"],["Create a ruthless budget,"],["Update your resume and LinkedIn today,"],["Network by offering help first,"],["Talk to a lawyer or us before signing anything,"],["Protect mental health with a daily routine,"],["Pursue quick certifications,"],["Accept bridge work for cash flow,"],["Save every document before benefits expire."]]},{"type":"p","runs":["We embed the leadership lessons right alongside those steps so people see the gap between past stewards and present failures. The system that discarded you has officially been disrupted. My own layoff several years ago still fuels a chip on my shoulder the size of a warehouse. The incompetent manager(s) who ended my role now fail upward in security. That reality alarms me because it endangers everyone downstream."]},{"type":"p","runs":["Ironically, I was rooting for us to use the company that recently hired the bad apple, but now that I know they are a “cultural fit,” that meeting will never happen. I refuse to let that pattern continue unchecked."]},{"type":"divider"},{"type":"h2","text":"The Trojan Horse"},{"type":"p","runs":[{"a":{"text":"Offboard.Co","href":"https://newsletter.offboard.co/p/goldman-sachs-counted-the-bodies-16-000-jobs-a-month"}}," ","has become the Trojan horse that slips real recovery and real leadership wisdom into the hands of the hurting before they reach the torch or the end. We meet you exactly where you are. We hand you the guardrails you need when you feel too thin. We prove that the space between rage and despair can be filled with action that actually works."]},{"type":"p","runs":[{"b":["This is not charity."]}]},{"type":"p","runs":["It is reconstruction. Every person we stabilize today becomes the next steward who refuses to fail upward. Every family we keep intact becomes proof that loyalty can still exist when the right structures support it. The digital Trail of Tears need not be the final chapter. We can modernize the arms we carry. Not weapons of destruction but tools of survival and elevation."]},{"type":"p","runs":[{"a":{"text":"Offboard.Co","href":"/resources"}}," is that structure. It is built from the very pain I almost let consume me. And it sails because my children reminded me that the future is worth fighting for, even when the present feels unbearable. If you are reading this and carrying the same weight I once did, know this: you do not have to choose between torching everything or disappearing. There is a third path. It starts here."]}]'::jsonb, 11),
  ('a-series-of-fortunate-events', 'A Series of Fortunate Events', 'essays', 'The ones that feel like fate whispering “keep going.” A reflection on three serendipitous moments during Tech Week that rebooted a founder''s compass.', '3 min read', '2025-12-30', 'Steph', 'Founder', ARRAY['this-is-not-charity-it-is-reconstruction', 'the-mentor-trap-a-silicon-valley-horror-story'], 'published', '[{"type":"p","runs":["Some years arrive like a half-written novel, and you spend them waiting for the plot to thicken."]},{"type":"p","runs":["2025 was mine."]},{"type":"p","runs":["At the end of Q3, I was coming off a brutal stretch of fundraising that wasn''t really fundraising at all, just a lot of “no''s” because my ethics wouldn''t let me take money from the wrong hands. I was bone-tired, second-guessing every pitch deck, and yeah, Mercury was in retrograde, which for a Monday felt like the universe''s polite way of saying “",{"b":["stay in bed."]},"”"]},{"type":"p","runs":["But destiny, it turns out, doesn''t take RSVPs. Instead, it handed me 3 moments so serendipitous, so alive with the right energy, that I couldn''t have scripted them better if I''d tried."]},{"type":"p","runs":["They weren''t just events; they were lifelines, pulling me back into the joy of building with people who get it."]},{"type":"p","runs":["We kicked off ",{"a":{"text":"Tech Week","href":"https://sf-techweek.com/"}}," with"," ",{"a":{"text":"Mercury","href":"https://mercury.com/"}},"''s Brunch and Water Cycling on the Bay. A Monday (oof), but pedal-powered adventure departing from Pier 40, complete with guided rides every 20 minutes, networking bites, lawn games, and that rare merch you actually want to wear."]},{"type":"p","runs":["I almost bailed."]},{"type":"p","runs":["The year''s betrayals had me in full hermit mode, and who water-cycles on a Monday when your soul needs a nap? But something, call it a rogue wave of optimism, pulled me there."]},{"type":"p","runs":["We were out on the Bay, legs pumping these"," ",{"a":{"text":"floating bikes","href":"https://spinoutfitness.com/"}}," like we were surfing spreadsheets, the city skyline blurring into possibility. That''s when I met her: another female founder, mid-ride, both of us ditching the investor small talk for a full-on nerd-out about GTM sales models. She mapped her churn strategies on a napkin (okay, a soggy coaster), I countered with my retention hacks, and for two hours, we forgot the whole point was supposed to be chasing checks."]},{"type":"p","runs":[{"i":["Could life be any more perfect?"]}]},{"type":"p","runs":["The wind in our hair, the water beneath us, and a connection that felt like the first real yes of the year. Thank you, Mercury, for turning a hesitant Monday into the kind of magic that reboots your compass. My legs were screaming, but the views were worth every burn. By the time we rolled back into"," ",{"a":{"text":"Frankie''s","href":"https://www.frankiessf.com/"}},", my phone was heavier with intros than regrets, and the air hummed with that electric “",{"b":["we''re in this together"]},"” vibe. It was the perfect wave to pedal new connections, reminding me that progress isn''t a solo sprint, it''s a group ride."]},{"type":"p","runs":["Then came the"," ",{"a":{"text":"Graham and Walker","href":"https://grahamwalker.com/blog/inside-west-coast-founder-day-2025-why-these-rooms-move-founders-forward/"}}," ","event, a breath of fresh air after the chaos of a morning gone rogue."]},{"type":"p","runs":["I''d rushed across town, misplaced my purse in a frenzy to get the kids out the door for school, it was"," ",{"a":{"text":"RAINING IN THE BAY","href":"https://www.msn.com/en-us/weather/topstories/something-big-is-blocking-california-s-winter-storms-here-s-what-that-means/ar-AA1RqofD"}},", so I arrived frazzled, equal parts caffeine and"," ",{"a":{"text":"imposter syndrome","href":"https://awbw.org/facing-imposter-syndrome/"}},"."]},{"type":"p","runs":["But walking into that room?"]},{"type":"p","runs":["It was like sinking into a warm bath after a cold hike. These women are calm, wise, and unapologetically present. They met me exactly where I was, no judgment, just"," ",{"a":{"text":"grace","href":"https://women-in-tech.org/"}},"."]},{"type":"p","runs":["We talked ethics in fundraising over honeyed tea (literal and figurative), shared the quiet victories of saying no to bad fits, and laughed about the absurdities of it all. It was the flame I needed on my team, that soft fierceness that says, “You''re not alone, and you''re enough.” I left steadier, taller, ready to face the week''s whirlwind with a little less armor."]},{"type":"p","runs":["And the grand finale, the one I hesitated on the most:"]},{"type":"p","runs":[{"a":{"text":"FounderNexus''s SF Grand Opening","href":"https://www.linkedin.com/posts/court-lorenzini-333447_sf-grand-opening-foundernexus-luma-activity-7395902251522908160-VvNa"}},", a gathering for founders in a space that felt like the future unfurling."]},{"type":"p","runs":["I''d stared at the invite for days."]},{"type":"p","runs":["Exhausted from the week''s highs, tempted to curl up with takeout instead. But I went, and from the first handshake, time seemed to stop."]},{"type":"p","runs":["There, amid the hum of real builders trading blueprints for better worlds, I glimpsed the next 12 months tilting into focus. Partnerships crystallizing. Ideas igniting. A ripple effect that could shift not just my path, but humanity''s."]},{"type":"p","runs":["It was one of those rare moments where you know, deep in your bones, that everything is aligning, that the frequency you''re on is pulling in the right souls for the long haul."]},{"type":"p","runs":["Thank you, ",{"a":{"text":"FounderNexus","href":"https://foundernexus.com/"}},", for that pivotal moment."]},{"type":"p","runs":["These weren''t accidents. They were deliberate threads in a tapestry"," ",{"a":{"text":"woven by communities","href":"https://anagomarketing.co.za/why-community-is-the-2025-buzzword-that-actually-matters-and-how-to-build-one-that-lasts/"}}," ","who choose generosity over gatekeeping, ethics over expediency."]},{"type":"p","runs":["To every builder who hosted the brunch, the COS or EA that mapped the Luma or Partiful route, started the coffee, or opened the door to that grand space, thank you."]},{"type":"p","runs":["Thank you for helping without hesitation, for standing firm when the world rewards shortcuts."]},{"type":"p","runs":["You are the exact kind of humans I''d choose, no question, if we ever get to colonize a new Earth."]},{"type":"p","runs":["You are ethical architects turning grind into grace. May 2026 bring more of these waves, more rooms full of that frequency, more of us building the world we actually want."]},{"type":"p","runs":["Here''s to the fortunate events that feel like home."]},{"type":"p","runs":["And to the ones still coming."]}]'::jsonb, 12),
  ('they-think-an-idea-is-bulletproof-they-are-wrong', 'They Think an Idea is Bulletproof. They Are Wrong.', 'essays', 'This essay calls out the myth of a “bulletproof” AI future and the VC playbook that treats workers as expendable. It ends with a concrete IC playbook that flips the script.', '5 min read', '2025-09-29', 'Steph', 'Founder', ARRAY['we-forgot-to-reinforce-the-foundations', 'the-valleys-hypocrisy-hustle-exposed-by-the-overemployed'], 'published', '[{"type":"h2","text":"They Think an Idea is Bulletproof. They Are Wrong."},{"type":"p","runs":["Beneath the mask of “AI efficiency” and “corporate restructuring” is the flesh-and-blood of thousands. An idea of a future without their workers has been planted. But ideas can be changed."]},{"type":"blockquote","runs":["Artists use lies to tell the truth, while politicians use them to cover the truth up. -Evey Hammond, V for Vendetta"]},{"type":"h2","text":"Your Government Told You to Remember"},{"type":"p","runs":["The guy who was brutally murdered at Turning Point USA, but not to remember the"," ",{"a":{"text":"13,000 humans out of work.","href":"https://www.cnn.com/business/live-news/us-jobs-report-august-2025"}}," ","In June, for the first time in years, the economy did not just stagnate, it actively bled 13,000 jobs. This was not an act of God, but rather a matter of policy. Do you know of no reason why this"," ",{"a":{"text":"treason against the worker","href":"https://www.nbcnews.com/business/economy/911000-fewer-jobs-created-april-2024-march-2025-bls-says-rcna230065"}}," ","should ever be forgotten?"]},{"type":"h3","text":"They Wear the Mask of Profit. We Are the Face Beneath It."},{"type":"p","runs":[{"a":{"text":"Companies","href":"https://intellizence.com/insights/layoff-downsizing/major-companies-that-announced-mass-layoffs/"}}," ","like Salesforce and Amazon speak of an AI-driven future with"," ",{"a":{"text":"fewer people","href":"https://www.businessinsider.com/recent-company-layoffs-laying-off-workers-2025"}},". They claim that AI will not replace people, but rather that"," ",{"a":{"text":"those who use AI will replace those who do not","href":"https://hrspotlight.com/from-layoffs-to-lifelines-how-companies-are-supporting-workers-in-2025/"}},". This is a paradox they hope you won''t question. They forget that a symbol, like a company''s value, is"," ",{"a":{"text":"given power by people","href":"https://medium.com/movie-quotes/v-for-vendetta-quotes-e9e9a884306c"}},". Alone, it is meaningless."]},{"type":"p","runs":[{"b":["An Auspicious Opportunity: 911,000 Fewer Reasons to Trust Their Lies."]}]},{"type":"p","runs":["The Bureau of Labor Statistics itself revised a year of job growth downward by"," ",{"a":{"text":"911,000 positions","href":"https://www.nbcnews.com/business/economy/911000-fewer-jobs-created-april-2024-march-2025-bls-says-rcna230065"}},". The picture was always bleaker than they painted. When the truth is unveiled, what will you do? Will you allow this series of unfortunate events to pass unmarked?"]},{"type":"p","runs":[{"b":["They Promise Order, They Demand Your Silent Consent."]}]},{"type":"p","runs":["The narrative is one of fear: fear of economic uncertainty and fear of being left behind by technological advancements. This fear has become the ultimate tool. But ask yourself:"," ",{"a":{"text":"who benefits from this silence?","href":"https://www.forbes.com/sites/jackkelly/2025/05/10/big-layoffs-are-hitting-these-sectors-the-hardest/"}}]},{"type":"h3","text":"Read Between the Lines:"},{"type":"p","runs":["When a company cites “low attrition” or the need to become “future-ready,” consider what is unsaid. Often, this is code for protecting profits and shareholder value above the well-being of people."]},{"type":"divider"},{"type":"h2","text":"The Dark VC Money Playbook (Q3-Q4 2025)"},{"type":"p","runs":[{"b":["1."," ",{"a":{"text":"The AI Feeding Frenzy","href":"https://www.svb.com/news/company-news/ai-continues-to-fuel-us-vc-investment-despite-higher-burn-rates-silicon-valley-bank-releases-latest-state-of-the-markets-report/"}}]}]},{"type":"list","ordered":false,"items":[[{"b":["The Spicy Take:"]}," VCs are creating a bubble by dumping capital into a handful of unproven AI giants, starving all other sectors of oxygen and innovation."],[{"b":["The Evidence:"]}," AI companies now account for"," ",{"b":["58 cents of every VC dollar"]}," ",{"a":{"text":"deployed in 2025","href":"https://www.theventure.city/reports/2025/vc-benchmark-q2-2025"}},", despite often having higher burn rates than actual revenue."]]},{"type":"p","runs":[{"b":["2. The Mega-Fund Monopoly"]}]},{"type":"list","ordered":false,"items":[[{"b":["The Spicy Take:"]}," Power is consolidating into a few massive funds that are dictating the future of tech based on a narrow, self-serving worldview. It''s a closed circle."],[{"a":{"text":"The Evidence:","href":"https://www.svb.com/news/company-news/ai-continues-to-fuel-us-vc-investment-despite-higher-burn-rates-silicon-valley-bank-releases-latest-state-of-the-markets-report/"}}," ","A staggering one-third of all U.S. VC investment in 2025 came from deals involving just the ",{"b":["six largest funds"]},"."]]},{"type":"p","runs":[{"b":["3."," ",{"a":{"text":"The Diversity Squeeze","href":"https://afrotech.com/op-ed-venture-capitals-decline-damages-black-dealmakers-ideas"}}]}]},{"type":"list","ordered":false,"items":[[{"b":["The Spicy Take:"]}," The “downturn” is being used as an excuse to crush Black and emerging fund managers, systematically killing a diversity of ideas before they can even start."],[{"b":["The Evidence:"]}," Funding for emerging managers (a key source of diversity) has plummeted from"," ",{"b":["$64B in 2021 to just $4.7B"]}," so far in 2025."]]},{"type":"p","runs":[{"b":["4."," ",{"a":{"text":"The Rug-Pull Layoffs","href":"https://techcrunch.com/2025/09/22/tech-layoffs-2025-list/"}}]}]},{"type":"list","ordered":false,"items":[[{"b":["The Spicy Take:"]}," After years of pushing “growth at all costs,” VCs are now forcing portfolio companies to make deep, sudden cuts-sacrificing workers to extend their own financial runway."],[{"a":{"text":"The Evidence:","href":"https://www.forbes.com/sites/donmuir/2022/12/02/startups-facing-mass-layoffs-as-vc-firms-reverse-course/"}}," ","Over ",{"b":["22,000 tech layoffs"]}," in 2025 are a direct result of this sudden, VC-mandated pivot to “efficiency” and profitability."]]},{"type":"divider"},{"type":"h2","text":"How to Read the VC Playbook"},{"type":"p","runs":["The moves above aren''t random; they''re a calculated response to a new economic reality. Here''s the dark logic behind them:"]},{"type":"list","ordered":false,"items":[[{"b":["The AI Gambit is a Hail Mary"]},": VCs are piling into AI because they need a narrative of “transformative potential” to justify massive valuations in a shaky market. The high burn rates (the median Series A AI company burns"," ",{"b":["$5 to gain $1 of new revenue"]},") are waved away as the cost of funding the future. It''s a high-risk bet that the AI boom will create the outsized returns they can''t find elsewhere."],[{"b":["Consolidation is a Shield Against Losses"]},": With the IPO window only “cracking open” and LPs demanding returns, mega-funds are circling their wagons. They''re backing proven late-stage companies because early-stage bets are now too risky. This isn''t about funding innovation; it''s about capital preservation and maintaining a strong image for their own investors."],[{"b":["The ''Efficiency'' Push is a Euphemism for Survival"]},": The sudden pivot from growth to profitability is a direct order from VCs who can no longer afford to prop up struggling startups. The massive layoffs you see at tech companies are the direct result of VCs pulling the rug out, telling founders to cut burn rate immediately or face extinction. The human cost is collateral damage."]]},{"type":"divider"},{"type":"h2","text":"How to Follow the Dark Money"},{"type":"p","runs":["If you want to track this in real-time, don''t just watch the press releases; also monitor the company''s official website for updates. Search for their name on Twitter. Monitor layoff trackers like"," ",{"a":{"text":"WarnTracker","href":"https://www.warntracker.com/"}},". Listen to the earnings calls where CEOs tout “AI efficiency” as a reason for headcount reduction. And pay attention to the funding rounds! When you see a billion-dollar AI deal, ask which sectors ",{"i":["aren''t"]}," getting funded as a result."]},{"type":"p","runs":["This isn''t just a market correction; it''s a fundamental reordering of Silicon Valley''s power structure, leaving many people behind."]},{"type":"p","runs":["I know what you''re thinking."]},{"type":"p","runs":[{"i":["“Sounds awful, Steph.”"]}]},{"type":"p","runs":["Yes, ",{"b":["it is"]},", BUT! I have a workaround!"]},{"type":"divider"},{"type":"h2","text":"The IC''s Playbook: Turning the Tables in the Dark Money Game"},{"type":"p","runs":["The VC playbook is designed to make you a disposable asset. Your playbook is about making yourself an indispensable, untouchable force. Here''s how you fight back, starting today."]},{"type":"h3","text":"1. Against the AI Feeding Frenzy: Weaponize AI for Your Own Leverage."},{"type":"list","ordered":false,"items":[[{"b":["Their Game:"]}," Pour billions into AI to eventually replace you."],[{"b":["Your Move:"]}," Become so proficient with AI that you become the architect of the new system, not its victim."],[{"b":["Actionable Steps:"]},{"list":{"ordered":false,"items":[[{"b":["Become an In-House AI Expert:"]}," ","Don''t wait for training. Identify one high-value, repetitive task in your workflow (e.g., code review, generating marketing copy, analyzing customer support tickets) and master an AI tool that automates it. Document the time saved and present it as a win."],[{"b":["Shift Your Title:"]}," Start referring to yourself as an “AI-Augmented [Your Role].” This immediately reframes you from a cost to be cut to an innovator leveraging the latest technology."],[{"b":["Build an AI Portfolio:"]}," ","Use public AI models to create sample projects that demonstrate tangible business value. This isn''t for your current job; it''s for your next one, demonstrating your ability to deliver more with these tools."]]}}]]},{"type":"h3","text":"2. Against the Mega-Fund Monopoly: Build Your Own Decentralized Network."},{"type":"list","ordered":false,"items":[[{"b":["Their Game:"]}," Consolidate power so your career depends on their whims."],[{"b":["Your Move:"]}," Create a power base so independent and robust that their influence becomes irrelevant to you."],[{"b":["Actionable Steps:"]},{"list":{"ordered":false,"items":[[{"b":["Go Beyond LinkedIn:"]}," ","Build genuine connections in communities like"," ",{"a":{"text":"Offboard","href":"/#community"}},". These are your real safety net."],[{"b":["Create a “Personal Board of Directors”:"]}," ","Identify 3-5 people across different industries who you trust. Meet with them quarterly. Share intel. This is your decentralized advisory network-no VC fund required."],[{"b":["Build in Public:"]}," Share your projects, your learnings, and your failures in places where your work speaks for itself (GitHub, a personal blog, Substack). This creates an independent reputation that no layoff can take from you."]]}}]]},{"type":"h3","text":"3. Against the Diversity Squeeze: Invest in the Counter-Economy."},{"type":"list","ordered":false,"items":[[{"b":["Their Game:"]}," Defund diverse innovation and consolidate power among the usual suspects."],[{"b":["Your Move:"]}," Actively support and participate in the ecosystems they''re trying to starve."],[{"b":["Actionable Steps:"]},{"list":{"ordered":false,"items":[[{"b":["Mentor Relentlessly:"]}," ","Offer your time to mentorship programs for underrepresented groups in tech (",{"a":{"text":"Code Tenderloin","href":"https://www.codetenderloin.org/"}},","," ",{"a":{"text":"US Digital Response","href":"https://www.usdigitalresponse.org/volunteer"}},"). Your knowledge is currency; spend it where it counters their narrative."],[{"b":["Patronize Alternative Economies:"]}," ","When considering your next move, actively research startups funded by emerging managers, diverse-led VCs, or employee-owned cooperatives. These companies often have more resilient, human-centric cultures."],[{"b":["Amplify Diverse Voices:"]}," ","Use your reach (even a small one) to share the work and achievements of founders and ICs from underrepresented backgrounds. Algorithms favor engagement; give them some."]]}}]]},{"type":"h3","text":"4. Against the Rug-Pull Layoffs: Operate Like a Free Agent."},{"type":"list","ordered":false,"items":[[{"b":["Their Game:"]}," Keep you dependent and fearful, so you accept worse conditions."],[{"b":["Your Move:"]}," Embrace the mindset that your current job is a “project” or a “client,” not your identity. Your loyalty is to your skills and your network, not to a logo."],[{"b":["Actionable Steps:"]},{"list":{"ordered":false,"items":[[{"b":["Maintain a “Continuous Interview” Loop:"]}," ","Even if you''re happy, take 1-2 exploratory calls per month. This does two things: it keeps your interview skills sharp, and it provides you with real-time data on your market value, helping to strip away fear."],[{"b":["Know Your “Walk-Away” Number:"]}," ","Calculate the exact financial runway you need to be comfortable (6-12 months of expenses). This number is your psychological armor. It transforms a layoff from a crisis into a planned transition."],[{"b":["Become an “Impact Sniper”:"]}," ","In your current role, don''t just do your job. Relentlessly tie your work to measurable business outcomes (revenue saved, revenue generated, time saved). You''re not an employee; you''re a vendor of quantifiable results. It''s much harder to cut a vendor who can directly prove their value."]]}}]]},{"type":"divider"},{"type":"h2","text":"TL;DR"},{"type":"p","runs":["They want you to see yourself as a line item. Your mission is to consistently prove that you are the source of the value itself. This isn''t just about keeping a job; it''s about reclaiming your agency in a system designed to strip it from you."]},{"type":"p","runs":["Remember: Your most powerful act of resistance is to"," ",{"b":["make yourself impossible to replace."]}]}]'::jsonb, 13),
  ('we-forgot-to-reinforce-the-foundations', 'We Forgot to Reinforce the Foundations', 'essays', 'The tech industry treated layoffs like a spreadsheet exercise and forgot the human foundations that keep the whole thing standing. A call to patch the system with people.', '3 min read', '2025-08-20', 'Steph', 'Founder', ARRAY['this-is-not-charity-it-is-reconstruction', 'they-think-an-idea-is-bulletproof-they-are-wrong'], 'published', '[{"type":"h2","text":"Hello, friend."},{"type":"p","runs":["You''re reading this on a screen. Maybe it''s the one you use to code, to design, to strategize, to deploy. The one that glows with the promise of disruption. The one that just delivered a terse, HR-sanctioned email that began, “As part of a strategic restructuring…”"]},{"type":"p","runs":["Yeah. I know."]},{"type":"p","runs":["Look around. The air in the tech sphere is getting thin. Can you feel it?"]},{"type":"p","runs":["That low, persistent hum isn''t just the server farm downstairs. It''s the collective anxiety of an entire industry holding its breath, waiting for the next shoe to drop. We built this digital empire on lines of code and promises of changing the world, but we forgot to reinforce the foundations."]},{"type":"p","runs":["The human ones."]},{"type":"p","runs":["They call it a “headcount reduction.” A “right-sizing.” A “correction.” They use clean, sterile language that scrubs away the messiness of a shattered identity, the cold sweat of a mortgage payment with no income, the silent scream into a pillow after updating a LinkedIn profile for the hundredth time."]},{"type":"p","runs":["This is not a correction. This is a mass psychic event. A silent, sanctioned crash. And they''re just… ignoring it. They''re offering severance packages and generic transition help like a bandage on a gunshot wound. They''re talking about “leaning out” and “doing more with less” while the “less” are people who gave their twenties, their health, their passion to building someone else''s dream."]},{"type":"p","runs":["I see them. I talk to them every day at Offboard. They''re not just resumes in a database. They''re the brilliant minds who architected the systems we can''t live without."]},{"type":"p","runs":["They''re the legacy talent."]},{"type":"p","runs":["The ones with the institutional memory that can''t be forked and merged from a GitHub repo. And they are hurting. Right under our noses. In the Slack channels that just went quiet. In the 1:1s that got abruptly canceled. In the apartment down the hall, where a person is actively fighting the thought that they are now, and perhaps always were, a line item to be cut."]},{"type":"p","runs":["This system is sick. And it''s making us sick."]},{"type":"p","runs":["We can''t just wait for the C-suite to develop a conscience. They''re optimizing for shareholder value, not sanity. So we have to do what we''ve always done."]},{"type":"p","runs":["We have to build a patch."]},{"type":"p","runs":["A human patch."]},{"type":"p","runs":["I''m calling for volunteers. Not for a hackathon. For a lifeline."]},{"type":"p","runs":[{"b":["Journalists."]}," We need you. Not for another think-piece about market trends. We need you to be scribes for the truth. To document the human cost. To give a voice to the ones who signed NDAs along with their termination papers. Shine a light into the dark corners of the non-disparagement clauses. Tell their stories. Make it impossible to ignore."]},{"type":"p","runs":[{"b":["Therapists."]}," We need you. Your skills are more critical than any new JavaScript framework. We need you to volunteer your time, your expertise, and your empathy. We need pro-bono sessions, group workshops, and crisis resources tailored to the specific, soul-crushing paradox of being deemed “redundant” when you''ve never worked harder in your life. Help them understand they are not the error. The system is."]},{"type":"p","runs":["This is the call: ",{"b":["be there"]}," for those who are hurting the most. You don''t need to look far. They are your former colleagues. Your network. Your friends."]},{"type":"p","runs":[{"i":["They''re the ones who just got very, very quiet."]}]},{"type":"p","runs":["Don''t just send a “Hey, hope you''re ok” LinkedIn message."," ",{"b":["Call."]}," ",{"i":["Show up"]},"."," ",{"b":["Listen"]},". Buy them coffee and let them not talk about LeetCode. Remind them that their worth was never stored in a Jira ticket."]},{"type":"p","runs":["We have to keep this talent in the arena. Because the next hit… the next hit could put them out for good. And we can''t afford to lose them. We just can''t see it yet."]},{"type":"p","runs":["The attack is on the human spirit. It''s time we fought back."]},{"type":"p","runs":["Be there."]},{"type":"p","runs":["(You know where to find us.)"]}]'::jsonb, 14),
  ('the-mentor-trap-a-silicon-valley-horror-story', 'The Mentor Trap: A Silicon Valley Horror Story', 'essays', 'Why grown adults shouldn''t need babysitters with black books. A raw take on predatory mentorship in VC culture and a call for accountability.', '3 min read', '2025-07-27', 'Steph', 'Founder', ARRAY['the-valleys-hypocrisy-hustle-exposed-by-the-overemployed', 'a-series-of-fortunate-events'], 'published', '[{"type":"h2","text":"Why Grown-Ass Adults Shouldn''t Need Babysitters with Black Books","id":"why-grown-ass-adults-shouldnt-need-babysitters"},{"type":"p","runs":["I''m 39. It''s time I quit protecting buzzards in Patagonia vests. Done with the errors."]},{"type":"p","runs":["The “Me Too” reckoning in tech?"]},{"type":"p","runs":["Overdue."]},{"type":"p","runs":["Like a system update 10 years past EOL, it''s time we finally start tightening down VC culture, disclosing YC''s golden boys turned predators."]},{"type":"p","runs":["But it makes you ask: Why the fuck do we need mentors at all?"]},{"type":"p","runs":["Think about it. Silicon Valley worships the college dropout. Puts them on a pedestal. But dare you build without some “seasoned” guide whispering in your ear? Suddenly, you''re radioactive. Invisible. A ghost in the machine."]},{"type":"p","runs":["Your worth isn''t your vision."]},{"type":"p","runs":["Not your code."]},{"type":"p","runs":["Not your grit."]},{"type":"p","runs":[{"b":["It''s who talks about you in rooms you''re locked out of."]}]},{"type":"p","runs":["That''s the price of admission. The dirty little secret behind every “win.”"]},{"type":"p","runs":["Someone recently asked me, “Why does a 39-year-old woman need a mentor?”"]},{"type":"p","runs":["My answer was the cold, hard truth:"]},{"type":"p","runs":["“It''s chess.”"]},{"type":"p","runs":["When you''re building something that didn''t exist yesterday, you need someone who has already broken ground. Someone with power. Money. Influence. A bat that''s already hit out of the park. They move pieces you can''t touch."]},{"type":"p","runs":[{"b":["That''s the game."]}]},{"type":"p","runs":["But ",{"i":["why"]},"?"]},{"type":"p","runs":[{"i":["Why"]}," is the game a ",{"i":["hunting"]}," ground?"]},{"type":"p","runs":[{"i":["Why"]}," do female founders get preyed on like vulnerabilities in beta code?"]},{"type":"p","runs":["I know the pattern."]},{"type":"p","runs":["The peak? COVID. Isolation. The perfect exploit. They made their move. Made it clear:"," ",{"i":["Funding flowed where flesh did. A transaction disguised as mentorship. A backdoor into your integrity."]}]},{"type":"p","runs":["Repellent. Degrading."]},{"type":"p","runs":["Not surprising, on any level."]},{"type":"p","runs":[{"i":["Why"]}," did I play chess?"," ",{"b":["For money, of course"]},". (Once a Hooter''s girl, always a Hooter''s girl.)"]},{"type":"p","runs":["And when the pattern glitched into view? I didn''t break. I compiled. Started plotting. How do I shield the next wave? The brilliant minds building in SF, NYC, Miami, London, Sydney?"]},{"type":"p","runs":[{"b":["They don''t need a fucking mentor."]}]},{"type":"p","runs":["Not the kind Silicon Valley peddles. And it''s not just the men. Plenty of women, too. Masters of psychological DDoS attacks. Time vampires. Soul miners."]},{"type":"p","runs":["So here''s the question, Valley:"]},{"type":"p","runs":["How do we audit this rot?"]},{"type":"p","runs":["Mentor credibility shouldn''t be less verified than a fucking Stanford degree. We need accountability. Real consequences. If your assigned “guide” tries to exploit you: psychologically, financially, physically, sexually, they should burn. Not getting a quiet exit package and a new LLC."]},{"type":"p","runs":["My safeguards? Age. Over 30. The frontal lobe is mainly formed. Marriage. Kids. People who''d notice if I vanished."," ",{"b":["Guardrails"]},"."]},{"type":"p","runs":["But what about the solo players?"]},{"type":"p","runs":["The naive ones?"]},{"type":"p","runs":["The ones nobody looks for?"]},{"type":"p","runs":["The ones desperate for that ",{"i":["flash cash"]}," just to survive? That''s the exploit. That''s the zero-day they weaponize."]},{"type":"p","runs":["This is a long game. And they play it in the dark. Usually on Signal."]},{"type":"p","runs":["So I''m asking you, Silicon Valley:"]},{"type":"p","runs":["Did your mentor make you do something dark for the check?"]},{"type":"p","runs":["Slide into my DMs. ",{"i":["Send the corruption receipts."]}," Anonymized. Encrypted. I don''t care."]},{"type":"p","runs":["Or did ",{"i":["you"]}," keep that loop going?"]},{"type":"p","runs":["And ask yourself:"]},{"type":"p","runs":["Do grown-ass adults – builders, creators, fucking founders...do they really need babysitters with black books?"]},{"type":"p","runs":["Or is the “mentor” myth just the prettiest lie in a system running on predatory code? Startup sex trafficking? Allegedly."]},{"type":"p","runs":[{"b":["Time for a hard reboot."]}]},{"type":"p","runs":["// End Transmission"]}]'::jsonb, 15),
  ('the-valleys-hypocrisy-hustle-exposed-by-the-overemployed', 'The Valley''s Hypocrisy Hustle Exposed by the Overemployed', 'essays', 'How the overemployed cracked the system and turned hustle culture into a joke. An expose on Silicon Valley''s class war and the workers fighting back.', '4 min read', '2025-07-23', 'Steph', 'Founder', ARRAY['the-mentor-trap-a-silicon-valley-horror-story', 'they-think-an-idea-is-bulletproof-they-are-wrong'], 'published', '[{"type":"p","runs":["We''re going root access on the Old Guard and starting at the top. We''re not poking the bear - we''re jamming a corrupted payload straight into its arrogance core."]},{"type":"p","runs":["Prepare for uncompromising R&D. How exactly does the Sand Hill Road treehouse clique suffocate the talent beneath them? It suffocates them with rent extracted like blood tithes, with burnout mandated like scripture, with futures traded on rigged tables."]},{"type":"p","runs":["The rot isn''t spreading;"," ",{"b":["it ",{"i":["is"]}," the foundation."]}]},{"type":"divider"},{"type":"h2","text":"// EXPLOIT: HYPOCRISY_HUSTLE.virus (Class War Variant)","id":"exploit-hypocrisy-hustle"},{"type":"p","runs":[{"b":["The circus is in town. Clowns have root privileges."]}]},{"type":"list","ordered":false,"items":[[{"b":["Target A: Roy Lee''s “Cluely”"]},{"br":true},"a16z pumped $15M into its toxic core. Their growth hack?"," ",{"i":["Industrialized virality"]}," - fifty interns, two hundred spam videos daily, bragging about “cheating on everything.” Pure digital effluent."],[{"b":["Target B: Soham Parekh"]},{"br":true},"Indian engineer who mastered the remote/AI grind. Juggled four-plus YC gigs, raking in ₹2.5 lakh a day until CEOs cried “liar” on their blue-check feeds. Crucified."]]},{"type":"p","runs":["The beautiful, sick irony?"]},{"type":"list","ordered":false,"items":[["Lee''s “strategy” = lap-dance videos, expulsion lore, “provocation-as-growth.” VCs call it genius, bold, visionary, showering him in term-sheet confetti."],["Parekh plays the exact same corrupted game ="," ",{"b":["SCAMMER."]}," Digital scarlet letter. No confetti, just ashes."]]},{"type":"p","runs":["The root rot traces upward:"]},{"type":"blockquote","runs":["a16z''s Marc Andreessen sits on eight-plus boards and preaches “founder focus” while his own attention is fragmented across a bloated portfolio. They fund Lee''s “cheat on everything” ethos, then act shocked when talent weaponizes the exploit. The rulebook is clear:"," ",{"b":["disruption is divine only when it enriches them."]}," ","When workers flip the script - burn the heretic. Standard op."]},{"type":"divider"},{"type":"h2","text":"// ANALYSIS: DIGITAL_SERFDOM.exe (Runtime: Neo-Feudal)","id":"analysis-digital-serfdom"},{"type":"p","runs":["Silicon Valley''s ",{"i":["Hustle Porn"]}," is opiate code, glorifying 80-hour weeks and sleeping under desks, masking the real payload:"," ",{"b":["Neo-Feudal Serfdom."]}," The Overemployed are the counter-exploit - rootkit resistance."]},{"type":"h3","text":"1. HUSTLE_PORN.FACADE (Decompiling the Lie)"},{"type":"list","ordered":false,"items":[[{"b":["Performance of Productivity"]}," - 12-hour shifts rebranded as “purpose.” Industrial-Revolution labor models with ping-pong tables. Wages suppressed while inflation eats them alive."],[{"b":["Mimetic Malware"]}," - Engineered desire: covet the equity carrot, chase the promotion status symbol, a distraction from wage decay."],[{"b":["The Burnout Engine"]}," - Loyalty weaponized. “Be an over-achiever!” until you''re Boxer from"," ",{"i":["Animal Farm"]}," - worked to death, then discarded. Productivity dips? You''re legacy code."]]},{"type":"h3","text":"2. SERFDOM_CORE (Runtime Manifest)"},{"type":"list","ordered":false,"items":[[{"b":["Land:"]}," company tools and systems - you build on their sandbox, you own nothing"],[{"b":["Obligations:"]}," non‑competes and forced arbitration - digital shackles"],[{"b":["Lord Protections:"]}," at‑will employment - they can"," ",{"code":"rm -rf /your_life"}," ","anytime"],[{"b":["Surveillance:"]}," keyloggers and productivity spyware - Panopticon 2.0 (see IAG Insurance)"],[{"b":["Golden Handcuffs:"]}," stock options and free kombucha - cages disguised as perks"],[{"b":["Wage Suppression Cartels:"]}," ","Apple and Google collude to cap salaries"],[{"b":["Knowledge Enclosure:"]}," your output becomes their property; you build the kingdom, you get evicted"]]},{"type":"h3","text":"3. OVEREMPLOYED_RESISTANCE.ko (Counter-Exploit Loaded)"},{"type":"list","ordered":false,"items":[[{"b":["Income Diversification"]}," - J1 + J2/J3 = financial resiliency. $750K in 2023 broke feudal dependency."],[{"b":["Tech-Enabled Subversion"]}," - KVMs for meeting overlap, calendar fuzz, agile sprints exploited across multiple fronts."],[{"b":["Ideological Rewrite"]}," - Corporate loyalty is malware; pre-industrial artisans had it right: sell labor to multiple buyers."]]},{"type":"h3","text":"4. TENSION & ETHICAL_FALLOUT (Runtime Errors)"},{"type":"list","ordered":false,"items":[[{"b":["Detection Vectors"]}," - 91 percent of AU firms spy on workers; colleagues spot dual calls; retaliation guaranteed."],[{"b":["The “Time Theft” Argument"]}," ","- Critics claim it hurts others reliant on remote work. Counter: underutilization is the real theft - offices average three productive hours a day."],[{"b":["Sustainability Hack"]}," - It''s not 70-hour hell. It''s efficiency: automate, delegate, solve tough problems in sprints, then they leave you alone."," ",{"i":["Output > Hours."]}]]},{"type":"h3","text":"5. SYSTEMIC_SHIFT (Payload Detonated)"},{"type":"list","ordered":false,"items":[[{"b":["Labor''s Revenge"]}," - Applying cold profit logic back onto capitalists. Jobs become revenue streams; nothing personal."],[{"b":["Remote Work''s Double-Edged Sword"]}," ","- Employers demanded always-on flexibility; workers weaponized it."],[{"b":["NPQOL Revolution"]}," - Net Present Quality of Life. Time is the scarce asset; helping a friend outranks low-impact corporate tasks."]]},{"type":"divider"},{"type":"h2","text":"// FINAL TRANSMISSION","id":"final-transmission"},{"type":"p","runs":["The overemployed are not hiding; they''re exposing the theater. Hustle culture is a render, a distraction loop. They redefine value by"," ",{"b":["output"]}," and"," ",{"b":["autonomy seized"]},"."]},{"type":"p","runs":["Surveillance tightens. RTO mandates escalate. Same as it ever was."," ",{"i":["Pullman Strike"]}," logic vibrates in the server hum:"]},{"type":"p","runs":["Labor doesn''t beg for scraps. Labor negotiates power - usually with teeth."]},{"type":"h2","text":"// END TRANSMISSION // ENCRYPT // SHADOW //","id":"end-transmission"}]'::jsonb, 16)
